function GlobeProcess() {
  const containerRef = useRef<HTMLDivElement>(null)
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ['start start', 'end end'],
  })
  const [activeStep, setActiveStep] = useState(0)

  useMotionValueEvent(scrollYProgress, 'change', (latest) => {
    const step = Math.min(Math.floor(latest * processSteps.length), processSteps.length - 1)
    setActiveStep(Math.max(0, step))
  })

  return (
    <div ref={containerRef} style={{ height: '400vh' }}>
      <div className="sticky top-0 h-screen flex items-center bg-[var(--brand-bg-dark)] overflow-hidden">
        <div className="w-full max-w-7xl mx-auto px-6 lg:px-12 grid lg:grid-cols-2 gap-16 items-center">
          {/* Left: steps */}
          <div>
            <p className="text-[var(--brand-accent)] text-xs font-bold uppercase tracking-[0.2em] mb-4">Our Process</p>
            <h2 className="text-[clamp(2rem,4vw,3.5rem)] font-[family-name:var(--font-display)] font-bold text-white leading-tight mb-12">
              Making <span className="italic text-[var(--brand-accent-green)]">business magic</span> in four moves
            </h2>
            <div className="space-y-6">
              {processSteps.map((step, i) => (
                <motion.div
                  key={step.number}
                  className={`p-6 rounded-2xl transition-all duration-500 ${
                    activeStep === i ? 'bg-white/5 border border-white/10' : 'opacity-40'
                  }`}
                  animate={{ opacity: activeStep === i ? 1 : 0.4 }}
                >
                  <div className="flex items-start gap-4">
                    <span className="text-[var(--brand-accent)] font-mono text-sm font-bold mt-1">{step.number}</span>
                    <div>
                      <h3 className="text-xl font-bold text-white mb-2">{step.title}</h3>
                      <AnimatePresence mode="wait">
                        {activeStep === i && (
                          <motion.p
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: 'auto' }}
                            exit={{ opacity: 0, height: 0 }}
                            className="text-white/50 text-sm leading-relaxed"
                          >
                            {step.description}
                          </motion.p>
                        )}
                      </AnimatePresence>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>

          {/* Right: globe */}
          <div className="hidden lg:flex items-center justify-center relative">
            <motion.div
              className="w-80 h-80 rounded-full globe-glow relative"
              style={{
                background: 'radial-gradient(circle at 30% 30%, #2A4A2A, #111112 70%)',
                border: '1px solid rgba(130, 255, 40, 0.2)',
              }}
              animate={{ rotate: activeStep * 90 }}
              transition={{ duration: 1.2, ease: [0.25, 0.46, 0.45, 0.94] }}
            >
              {/* Grid lines */}
              <div className="absolute inset-0 rounded-full overflow-hidden opacity-20">
                {[...Array(5)].map((_, i) => (
                  <div key={`h-${i}`} className="absolute w-full border-t border-[var(--brand-accent-green)]" style={{ top: `${(i + 1) * 16.6}%` }} />
                ))}
                {[...Array(5)].map((_, i) => (
                  <div key={`v-${i}`} className="absolute h-full border-l border-[var(--brand-accent-green)]" style={{ left: `${(i + 1) * 16.6}%` }} />
                ))}
              </div>

              {/* Step indicators on globe */}
              {processSteps.map((step, i) => {
                const angle = (i * 90 - 45) * (Math.PI / 180)
                const radius = 120
                const x = Math.cos(angle) * radius
                const y = Math.sin(angle) * radius
                return (
                  <motion.div
                    key={step.number}
                    className={`absolute w-10 h-10 rounded-full flex items-center justify-center text-xs font-bold transition-all duration-500 ${
                      activeStep === i
                        ? 'bg-[var(--brand-accent-green)] text-black scale-125'
                        : 'bg-white/10 text-white/50'
                    }`}
                    style={{
                      left: `calc(50% + ${x}px - 20px)`,
                      top: `calc(50% + ${y}px - 20px)`,
                    }}
                  >
                    {step.number}
                  </motion.div>
                )
              })}
            </motion.div>
          </div>
        </div>
      </div>
    </div>
  )
}

      {/* ── PROCESS — Globe ── */}
