      </section>

function Counter({ target, prefix = '', suffix = '', duration = 2, className = '' }: { target: number; prefix?: string; suffix?: string; duration?: number; className?: string }) {
  const ref = useRef(null)
  const isInView = useInView(ref, { once: true })
  const count = useMotionValue(0)
  const rounded = useTransform(count, (v: number) => `${prefix}${Math.round(v).toLocaleString()}${suffix}`)
  const [display, setDisplay] = useState(`${prefix}0${suffix}`)

  useEffect(() => {
    if (isInView) {
      const controls = animate(count, target, { duration, ease: 'easeOut' })
      return controls.stop
    }
  }, [isInView, count, target, duration])

  useEffect(() => {
    const unsubscribe = rounded.on('change', (v: string) => setDisplay(v))
    return unsubscribe
  }, [rounded])

  return <span ref={ref} className={className}>{display}</span>
}

