function SlidingRow({ items, direction }: { items: typeof galleryItems; direction: 'left' | 'right' }) {
  const ref = useRef(null)
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] })
  const x = useTransform(
    scrollYProgress,
    [0, 1],
    direction === 'left' ? ['8%', '-8%'] : ['-8%', '8%']
  )

  return (
    <motion.div ref={ref} className="flex gap-5 py-3" style={{ x }}>
      {items.map((item, i) => (
        <motion.div
          key={item.label}
          className={`relative flex-shrink-0 w-[320px] md:w-[400px] ${item.aspect} rounded-xl overflow-hidden group cursor-pointer`}
          initial={{ opacity: 0, x: direction === 'left' ? -80 : 80 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true, margin: '-40px' }}
          transition={{ duration: 0.8, delay: i * 0.1, ease: [0.25, 0.46, 0.45, 0.94] }}
        >
          <div className={`absolute inset-0 bg-gradient-to-br ${item.gradient} group-hover:scale-110 transition-transform duration-700`} />
          <div className="absolute inset-0 bg-black/25 group-hover:bg-black/10 transition-all duration-500" />
          <span className="absolute bottom-4 left-5 text-white/80 text-xs uppercase tracking-[0.2em] z-10 font-medium">{item.label}</span>
        </motion.div>
      ))}
    </motion.div>
  )
}

