function RevealWord({
  word, index, total, progress, phaseStart, phaseEnd,
}: {
  word: string; index: number; total: number
  progress: ReturnType<typeof useScroll>['scrollYProgress']
  phaseStart: number; phaseEnd: number
}) {
  const range = phaseEnd - phaseStart
  const wordStart = phaseStart + (index / total) * range
  const wordEnd = phaseStart + ((index + 1) / total) * range
  const color = useTransform(progress, [wordStart, wordEnd], ['#d4d4d4', '#1A1A1A'])
  return (
    <motion.span style={{ color }} className="inline-block mr-[0.3em]">
      {word}
    </motion.span>
  )
}

