function ScrollCard({
  num, title, desc, progress, index, total, startOffset,
}: {
  num: string; title: string; desc: string
  progress: ReturnType<typeof useScroll>['scrollYProgress']
  index: number; total: number; startOffset: number
}) {
  const cardRange = 1 - startOffset
  const segment = cardRange / total
  const start = startOffset + index * segment
  const end = startOffset + (index + 1) * segment
  const fadeIn = start + segment * 0.15
  const holdStart = start + segment * 0.25
  const holdEnd = start + segment * 0.7
  const fadeOut = start + segment * 0.85

  const opacity = useTransform(
    progress,
    [start, fadeIn, holdStart, holdEnd, fadeOut, end],
    [0, 0, 1, 1, 0, 0]
  )
  const y = useTransform(
    progress,
    [start, holdStart, holdEnd, end],
    [40, 0, 0, -30]
  )

  return (
    <motion.div style={{ opacity, y }} className="absolute top-[50%] -translate-y-1/2 left-8 lg:left-20 z-10 max-w-[520px]">
      <span className="inline-block mb-5 px-4 py-2 text-sm rounded-full bg-[var(--brand-sage)] text-[var(--brand-text)] font-medium">{num}</span>
      <h2 className="text-[clamp(2.5rem,5vw,4rem)] font-semibold tracking-[-0.04em] leading-[1.08] text-[var(--brand-text)] whitespace-pre-line">{title}</h2>
      <p className="mt-6 text-[var(--brand-muted)] leading-relaxed max-w-[440px]">{desc}</p>
    </motion.div>
  )
}

