            <a href="#fleet" className="inline-flex items-center gap-2 mt-8 text-[var(--brand-accent)] text-sm font-semibold hover:gap-3 transition-all">
              View More <ChevronRight className="w-4 h-4" />
            </a>

            {/* Specs */}
            <div className="mt-12 grid grid-cols-3 gap-6">
              <div>
                <p className="text-white/40 text-xs uppercase tracking-widest mb-1">Length</p>
                <p className="text-white text-2xl font-semibold">{boat.length}</p>
              </div>
              <div>
                <p className="text-white/40 text-xs uppercase tracking-widest mb-1">Top Speed</p>
                <p className="text-white text-2xl font-semibold">{boat.speed}</p>
              </div>
              <div>
                <p className="text-white/40 text-xs uppercase tracking-widest mb-1">Guests</p>
                <p className="text-white text-2xl font-semibold">{boat.guests}</p>
              </div>
            </div>

            {/* Nav arrows */}
            <div className="mt-10 flex items-center gap-3">
              <button onClick={prev} className="w-12 h-12 rounded-full border border-white/20 flex items-center justify-center text-white hover:bg-white/10 transition">
