              </button>
              <span className="ml-3 text-white/40 text-sm">{current + 1} / {allBoats.length}</span>
            </div>
          </motion.div>

          {/* Right: Image */}
          <motion.div
            key={boat.image}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.6 }}
            className="relative"
          >
            <div className="aspect-[4/3] rounded-2xl overflow-hidden relative">
              <img
                src={boat.image}
